from collections import namedtuple

EOL = b'\r\n'
SPACE = EOL + b'\x00\x09\x0c\x20'

def skip_chars(chars, text, i):
    """ syntax
    """
    while i < len(text):
        if text[i] not in chars: return i
        i += 1
    return None        


def next_token(text, i):
    """ syntax Find next token in raw string starting at some index
    """
    search = "TBD"
    nested = 1
    h = i
    while i < len(text):
        single = text[i:i+1]
        double = text[i:i+2]
        if search == "TBD":
            if double == b'<<':
                search = "DICT"
            elif single == b'[':
                search = "ARRAY"
            elif single == b"/":
                search = "NAME"
            elif text[i:i+6] == b"stream":
                search = "STREAM"
                offset = 7 if text[i+6:i+7] == b'\n' else 8 # else is b'\r\n'
                i += offset
            elif single in b"+-.0123456789":
                search = "VALUE"
            elif single in b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ":
                search = "KEYWORD"
            elif single in b"(<":
                search = "TEXT"
            h = i
        elif search == "DICT":
            if double == b'<<':
                nested += 1
                i += 1
            elif double == b'>>':
                nested -= 1
                i += 1
            if nested == 0:
                return (h, i + 1, 'DICT')
            else:
                pass
        elif search == "NAME":
            if single in b' \n\r[]/<>(':
                return (h, i, 'NAME')
        elif search == "TEXT":
            if double == b'\\(' or double == b'\\)' or double == b'\\<' or double == b'\\>':
                i += 1
            else:    
                if single in b')>':
                    return (h, i + 1, 'TEXT')
        elif search == "KEYWORD":
            if single in b' \n\r>/]' or i == len(text) - 1:
                return (h, i, 'KEYWORD')
        elif search == "VALUE":
            if single in b' \n\r>/]' or i == len(text) - 1:
                return (h, i, 'VALUE')
        elif search == "STREAM":
            if text[i:i+11] == b'\r\nendstream' or text[i:i+10] == b'\nendstream':
                return (h, i, 'STREAM')
        elif search == "ARRAY":
            if single == b'[':
                nested += 1
            elif single == b']':
                nested -= 1
            if nested == 0:
                return (h, i + 1, 'ARRAY')
        i += 1
    return (h, i + 1, '')


def replace_ref(tokens):
    """ syntax
    """
    size = len(tokens)
    new_list = []
    i = 0
    while i < size:
        if i < size - 2 and tokens[i + 2]  == b'R':
            new_list.append({'_REF': tokens[i]})
            i += 3
        else:
            new_list.append(tokens[i])
            i += 1
    return new_list

def decode_predictor(bdata, predictor, columns):
    size = len(bdata)
    res = b''
    columns += 1
    prev_row = [0] * columns
    i = 0
    while i < size:
        row = list(bdata[i:i+columns])
        decoded_row = [(val + prev_row[index]) & 0xff for (index, val) in enumerate(row)]
        prev_row = decoded_row
        res += bytes(decoded_row[1:])
        i += columns
    return res


def decode_stream(stream, stream_def):
    res = stream
    if b'/Filter' in stream_def and stream_def[b'/Filter'] == b'/FlateDecode':
        res = zlib.decompress(stream) #+ b'\r')
    if b'/DecodeParms' in stream_def and b'/Predictor' in stream_def[b'/DecodeParms']:
        predictor = int(stream_def[b'/DecodeParms'][b'/Predictor'])
        columns = int(stream_def[b'/DecodeParms'][b'/Columns'])
        res = decode_predictor(res, predictor, columns)
    return res


def parse_obj(text, start=0):
    """ syntax
    """
    ref_list = []
    h1, j1, t1 = next_token(text, start)
    obj = text[h1:j1]
    if t1 == 'DICT':
        res = {}
        res_array = []
        h2, j2, t2 = next_token(text, j1)
        following_obj = text[h2:j2]
        if t2 == 'STREAM': 
            stream_def =  parse_obj(obj)
            stream_content = decode_stream(following_obj, stream_def)
            res = { 'stream_def': stream_def, 'stream_content': stream_content }
            return res

        i = start + 2
        while i < j1:
            h, i, ttt = next_token(text, i)
            if i < j1 and ttt:                             # TODO ?
                if ttt == 'DICT' or ttt == 'ARRAY':
                    obj = parse_obj(text[h:i])
                else:
                    obj = text[h:i]
                res_array.append(obj)
        toggle = True
        res_array = replace_ref(res_array)
        j = len(res_array) - 1
        while j >= 0:
            if toggle:
                val = res_array[j]
                toggle = False
            else:
                key = res_array[j]
                res[key] = val
                toggle = True
            j -= 1
        return res

    elif t1 == 'ARRAY':
        res = []
        i = start + 1
        while i < j1:
            h, i, ttt = next_token(text, i)
            if ttt:
                obj = text[h:i]
                res.append(obj)
        res = replace_ref(res)
        return res
    else:
        return None


def beginning_next_non_empty_line(bdata, i):
    """ doc
    """
    while bdata[i] not in EOL:
        i += 1
    while bdata[i] in EOL:
        i += 1
    return i

"""Module pdfsyntax.display: pretty print the PDF file structure as HTML"""

import html

NAME_MAX_WIDTH = 20
VALUE_MAX_WIDTH = 40

HEADER = '''
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>pdfsyntax</title>
    <style>
        body {
            font-family: monospace;
        }
        :target {
            background-color: LightYellow;
        }
        .obj-header {
            background-color: LightGray;
        }
        .obj-body {
            background-color: WhiteSmoke;
            margin: 0 0 0 0;
        }
        .obj-low {
            color: Gray;
        }
        .obj-link {
            background-color: AliceBlue;
        }
        .eof {
            background-color: AntiqueWhite;
        }
        .header-button {
            background-color: AliceBlue;
            color: Grey;
        }
        .header-link {
            color: Grey;
        }
        .important {
            background-color: AntiqueWhite;
        }
        .header {
            position: fixed;
            top: 0px;
            left: 0px;
            width: 100%;
            background-color: Black;
            color: White;
        }
        .content {
            margin-top: 5em;
        }
    </style>
</head>
<body>
'''

TRAILER = '''
</div>
</body>
'''

TRUNCATED = '<em> ...(truncated) </em>'


def build_html(articles, pos_index, filename):
    """Compose the page layout"""
    page = HEADER
    last_o = max(list(pos_index.keys()))
    startxref = pos_index[last_o]
    page += build_header(filename, startxref)
    for article in articles:
        obj_attr = (article['o_num'], article['o_gen'], article['o_ver'])
        obj = article['content']
        mini_index = article['mini_index']
        if obj_attr[0] == -1:
            page += add_startxref(article, pos_index)
            continue
        elif obj_attr[0] == -2:
            page += add_eof(article)
            continue
        page += build_obj_header(article)
        if 'xref_table' in article:
            page += build_xref_table(article['xref_table'], mini_index)
        page += follow_obj(obj, mini_index, pos_index)
        page += build_obj_trailer()
    page += TRAILER
    return page

def build_header(filename, startxref):
    """Add a banner with the file name"""
    ret = ''
    ret += f'<div class="header">\n'
    ret += f'<pre> <a class="header-button" href="#obj{startxref}">jump to startxref</a>'
    ret += f'     <span class="obj-low">Hypertext inspection of </span>{filename}<span class="obj-low"> generated by </span>'
    ret += f'<a class="header-link" href="https://github.com/desgeeko/pdfsyntax">pdfsyntax</a></pre>'
    ret += f'</div>\n'
    ret += f'<div class="content">\n'
    return ret

def add_startxref(article, pos_index):
    """ """
    o_num, o_gen, o_ver = article['o_num'], article['o_gen'], article['o_ver']
    xref = article['content']
    ret = ''
    ret += f'<div id="obj{o_num}.{o_gen}.{o_ver}">\n<pre>\n'
    ret += f'startxref\n'
    if xref == 0:
        ret += f'0\n'
    else:
        ret += f'<a class="obj-link" href="#obj{pos_index[xref]}">{xref}</a>\n'                
    ret += f'\n</pre>\n</div>\n'
    return ret

def add_eof(article):
    """ """
    o_num, o_gen, o_ver = article['o_num'], article['o_gen'], article['o_ver']
    ret = ''
    ret += f'<div id="obj{o_num}.{o_gen}.{o_ver}">\n<pre class="eof">\n'
    ret += f'%%EOF\n'
    ret += f'</pre>\n</div>\n'
    return ret

def build_xref_table(table, mini_index):
    """Display XREF table with additional links to objects """
    ret = ''
    for line, o_num in table:
        ret += line.decode('ascii')
        if line[:10] != b'0000000000' and o_num != None:
            o_gen, o_ver = mini_index[o_num]
            ret += '    '
            ret += f'<a href="#obj{o_num}.{o_gen}.{o_ver}">'
            ret += f'<span class="obj-link">#{o_num} {o_gen}</span>'
            ret += '</a>'
        ret += '\n'
    return ret

def move_list_item(mod_list, item, new_pos):
    """Reposition an item in a list"""
    if item in mod_list:
        old_pos = mod_list.index(item)
        mod_list.pop(old_pos)
        mod_list.insert(new_pos, item)
    return mod_list

def follow_obj(obj, mini_index, pos_index, depth=0):
    """Recursively construct object representation"""
    ret = ''
    content = None
    if type(obj) == dict: 
        if 'stream_content' in obj:
            content = obj['stream_content']
        if 'stream_def' in obj:
            obj = obj['stream_def']
        if '_REF' in obj:
            o_num = int(obj['_REF'])
            o_gen, o_ver = mini_index[o_num]
            ret += f'<a href="#obj{o_num}.{o_gen}.{o_ver}">'
            ret += f'<span class="obj-link">{o_num} {o_gen} R</span>'
            ret += '</a>'
            return ret
        ret += '<<\n'
        keys = list(obj.keys())
        keys = move_list_item(keys, b'/Type', 0)
        keys = move_list_item(keys, b'/Subtype', 1)
        for i in keys:
            name = i.decode('ascii')
            value = follow_obj(obj[i], mini_index, pos_index, depth + 1)
            ret += ' ' * (NAME_MAX_WIDTH + 2) * depth
            if name == '/Type' or name == '/Subtype':
                ret += f'  {name:{NAME_MAX_WIDTH}}<span class="important">{value}</span>\n'
            elif name == '/Prev':
                ret += f'  {name:{NAME_MAX_WIDTH}}<a class="obj-link" href="#obj{pos_index[int(value)]}">{value}</a>\n'                
            else:
                ret += f'  {name:{NAME_MAX_WIDTH}}{value}\n'
        if content:
            content = f'{content}'[2:-1]
            content = content[:VALUE_MAX_WIDTH * 2] + TRUNCATED
            ret += f'  {"stream":{NAME_MAX_WIDTH}}{content}\n'                
        ret += ' ' * (NAME_MAX_WIDTH + 2) * depth
        ret += '>>'
    elif type(obj) == list:
        ret += '[ '
        nb_char = 0
        for i in obj:
            value = follow_obj(i, mini_index, pos_index)
            ret += f'{value} '
        if len(ret) > VALUE_MAX_WIDTH and 'href' not in ret:
            ret = ret[:VALUE_MAX_WIDTH] + TRUNCATED
        ret += ']'        
    else:
        comment = False
        if obj[0:1] == b'(':
            if len(obj) > VALUE_MAX_WIDTH:
                obj = obj[:VALUE_MAX_WIDTH]
                comment = True
            obj = f'{obj}'
            ret += f'{obj[2:-1]}'
        else:
            ret += obj.decode('ascii')
        ret = html.escape(ret)
        if comment == True:
            ret += TRUNCATED
    return ret

def build_obj_header(article):
    """Add opening elements to object"""
    obj = article['content']
    o_num, o_gen, o_ver = article['o_num'], article['o_gen'], article['o_ver']
    ret = ''
    ret += f'<div id="obj{o_num}.{o_gen}.{o_ver}">\n<pre>\n'
    if o_num == 0:
        ret += f'<span class="obj-header"><strong>XREF table & trailer</strong></span>\n'
    else:
        ret += f'<span class="obj-header"><strong>{o_num}</strong> <span class="obj-low">{o_gen} obj</span></span>'
        if 'abs_pos' in article:
            ret += f'<em class="obj-low">  at offset {article.get("abs_pos")}</em>'
        else:
            ret += f'<em class="obj-low">  from object stream {article.get("env_num")} above</em>'
    ret += f'<pre class="obj-body">\n'
    return ret

def build_obj_trailer():
    """Add closing elements to object"""
    ret = ''
    ret += f'</pre>\n'
    ret += f'\n</pre>\n</div>\n'
    return ret

